package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen1Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private AnnotatedMember mockProperty;
    private JavaType mockBaseType;

    public static class Base {}
    public static class Sub1 extends Base {}
    public static class Sub2 extends Base {}
    public static class Other {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockProperty = mock(AnnotatedMember.class);
        mockBaseType = mock(JavaType.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectSubtypes_NoPropertyNoRegistered() {
        // Test case where property is null and no subtypes are registered
        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        // Since it's the root type, it should return the root through _combineNamedAndUnnamed
        // depending on internal implementation of _combineNamedAndUnnamed
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectSubtypes_WithPropertySubtypes() {
        // Mock annotation introspector to return subtypes via property
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        List<NamedType> propertySubtypes = new ArrayList<>();
        propertySubtypes.add(namedSub1);

        when(mockAi.findSubtypes(mockProperty)).thenReturn(propertySubtypes);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
    }

    @Test
    public void testCollectSubtypes_WithPropertySubtypesNull() {
        // Test branch where ai.findSubtypes(property) returns null
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectSubtypes_WithRegisteredSubtypes() {
        // Register subtypes explicitly
        resolver.registerSubtypes(Sub1.class, Sub2.class);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub2.class)));
    }

    @Test
    public void testCollectSubtypes_WithRegisteredNonSubtypes() {
        // Register a class that is NOT a subtype of Base
        resolver.registerSubtypes(Other.class);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        // Other.class should not be in the collection because isAssignableFrom fails
        assertFalse(result.stream().anyMatch(nt -> nt.getType().equals(Other.class)));
    }

    @Test
    public void testCollectSubtypes_CombinedAllSources() {
        // 1. Property subtypes
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedSub1));

        // 2. Registered subtypes
        resolver.registerSubtypes(Sub2.class);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Check if both found via property and registered are present
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub2.class)));
    }

    @Test
    public void testCollectSubtypes_BaseTypeIsDifferent() {
        // Test with a base type that has no subtypes
        when(mockBaseType.getRawClass()).thenReturn(Other.class);

        resolver.registerSubtypes(Sub1.class); // Sub1 is not a subtype of Other

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Other.class)));
        assertFalse(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
    }
}
